    <script>function chatPolling(url){return{messages:@json($initialMessages),offers:@json($initialOffers),formatRupiah(v){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v)},offerStatus(v){return {pending:'Menunggu Persetujuan',accepted:'Diterima',rejected:'Ditolak',expired:'Kedaluwarsa',cancelled:'Dibatalkan',replaced:'Digantikan Penawaran Baru',checked_out:'Sudah Checkout'}[v]||v},start(){setInterval(()=>fetch(url,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(d=>{this.messages=d.messages;this.offers=d.offers.map(o=>({...o,checked_out:o.status==='checked_out'}))}),5000)}}}</script>
    <script>document.querySelector('select[name="product_id"]')?.addEventListener('change',function(){const product=this.options[this.selectedIndex]?.text||'';const variants=document.querySelector('select[name="product_variant_id"]');[...variants.options].forEach(option=>{if(option.value){option.hidden=!option.textContent.startsWith(product+' —');if(option.hidden&&option.selected)variants.value='';}});});</script>
